"""Compile one Zig module to an object file for the meson build.

Meson calls this for every `*.zig` module. It mirrors the C build's
configuration:

* the optimize mode follows meson's `--buildtype`
  (debug -> Debug, release -> ReleaseSafe, minsize -> ReleaseSmall)
* `build_options` mirrors meson feature options (grapheme clustering)
* `c_layout` (generated by `abi_probe.c`) is imported by
  `terminal_types.zig` to check the ABI mirror at compile time

Usage: compile_zig.py INPUT.zig OUTPUT.o [grapheme_clustering: true|false]
                                [name=value ...]

Extra `name=value` arguments are written to the generated `build_options`
module as `pub const name = value;`, so a module can mirror any meson
feature flag it needs.
"""

import json
import os
import subprocess
import sys

# The migration branch is developed against this Zig series.
ZIG_SERIES = "0.16"

OPTIMIZE_MODES = {
    "debug": "Debug",
    "debugoptimized": "ReleaseSafe",
    "release": "ReleaseSafe",
    "minsize": "ReleaseSmall",
}


def zig_version():
    try:
        out = subprocess.run(
            ["zig", "version"], capture_output=True, text=True, check=True)
    except (OSError, subprocess.CalledProcessError):
        sys.exit("compile_zig.py: could not run `zig version`; is Zig installed?")
    return out.stdout.strip()


def check_version(version):
    if not version.startswith(ZIG_SERIES + "."):
        sys.exit(
            f"compile_zig.py: Zig {ZIG_SERIES} is required (found {version})")


def meson_buildtype():
    root = os.environ.get("MESON_BUILD_ROOT")
    if not root:
        return None
    path = os.path.join(root, "meson-info", "intro-buildoptions.json")
    try:
        with open(path, "r", encoding="utf-8") as f:
            options = json.load(f)
    except (OSError, ValueError):
        return None
    for option in options:
        if option.get("name") == "buildtype":
            return option.get("value")
    return None


def main():
    if len(sys.argv) < 3:
        sys.exit(__doc__)

    input_file, output_file = sys.argv[1], sys.argv[2]
    grapheme_clustering = None
    extra_options: dict[str, str] = {}
    for arg in sys.argv[3:]:
        if "=" in arg:
            name, value = arg.split("=", 1)
            # A value is either a bool or a Zig string literal ("...").
            # The latter mirrors C string #defines (e.g. a path).
            is_string = len(value) >= 2 and value[0] == '"' and value[-1] == '"'
            if value not in ("true", "false") and not is_string:
                sys.exit(
                    f"compile_zig.py: {name}: expected true/false or a "
                    f'quoted string, got {value!r}')
            extra_options[name] = value
        elif arg in ("true", "false"):
            grapheme_clustering = arg
        else:
            sys.exit(f"compile_zig.py: unexpected argument {arg!r}")

    check_version(zig_version())

    buildtype = meson_buildtype()
    optimize = OPTIMIZE_MODES.get(buildtype or "", "ReleaseSafe")

    cmd = ["zig", "build-obj", "-O", optimize, "-fno-stack-check", "-lc"]

    # Meson generates build_options next to the output, and c_layout.zig
    # likewise (unless the target predates the ABI probe).
    out_dir = os.path.dirname(os.path.abspath(output_file))
    opts_file = None
    if grapheme_clustering is not None or extra_options:
        opts_file = output_file + ".build_options.zig"
        with open(opts_file, "w", encoding="utf-8") as f:
            if grapheme_clustering is not None:
                f.write(
                    "pub const grapheme_clustering = %s;\n"
                    % ("true" if grapheme_clustering == "true" else "false"))
            for name, value in extra_options.items():
                f.write(f"pub const {name} = {value};\n")

    layout_file = os.path.join(out_dir, "c_layout.zig")
    if not os.path.exists(layout_file):
        layout_file = None

    deps = []
    if opts_file is not None:
        deps.append(("build_options", opts_file))
    if layout_file is not None:
        deps.append(("c_layout", layout_file))

    for name, path in deps:
        cmd += ["--dep", name]
    cmd += ["-Mroot=" + input_file]
    for name, path in deps:
        cmd += [f"-M{name}={path}"]

    cmd += ["-femit-bin=" + output_file]

    subprocess.run(cmd, check=True)


if __name__ == "__main__":
    main()
